import { z } from "zod";
import {
  cursor,
  deviceDirection,
  firstScan,
  gateName,
  keyBundle,
  scannerTicketType,
  scanRecord,
  syncTicket,
  ticketIdHex,
  unixSeconds,
  uuid,
} from "./common";

/** `POST /enroll` on the hub, and the exchange step of the cloud's `POST /devices/enroll`. */
export const enrollExchangeRequest = z.object({
  /** The one-time code from the `DEV1:` setup QR. */
  code: z.string().min(1).max(255),
  /** Generated by the phone so a retry is idempotent. */
  device_id: uuid,
});
export const enrollExchangeResponse = z.object({
  device_id: uuid,
  device_token: z.string().min(1),
  key_bundle: keyBundle,
  gate: gateName,
  direction: deviceDirection,
  label: z.string().nullable(),
});

const claimBody = z.object({
  scan_id: uuid,
  ticket_id: ticketIdHex,
  device_id: uuid,
  staff_id: uuid.nullable().optional(),
  gate: gateName,
  scanned_at: unixSeconds,
});

/**
 * `POST /claim`: atomic entry check-and-mark. `override` is a supervisor admitting a ticket the
 * device's list did not know (amber screen): `staff_id` must then be a supervisor, and the scan is
 * recorded as `override`.
 */
export const claimRequest = claimBody.extend({ override: z.boolean().optional() });
export const claimResponse = z.object({
  result: z.enum(["admitted", "rejected_used", "rejected_inside", "rejected_cancelled"]),
  admits_used: z.number().int().min(0).optional(),
  /** null = unlimited. */
  limit: z.number().int().nullable().optional(),
  /** The ticket's most recent admission: where, when and on which device (for red screens). */
  first_scan: firstScan.optional(),
});

/** `POST /exit`: re-entry tickets only; same body as `/claim`. */
export const exitRequest = claimBody;
export const exitResponse = z.object({
  result: z.enum(["exited", "no_reentry", "rejected_cancelled"]),
  entries_left: z.number().int().nullable().optional(),
});

/** `GET /sync?cursor=`: ticket changes, device setting changes and the hub clock. */
export const hubSyncQuery = z.object({ cursor: cursor.optional() });
export const hubSyncResponse = z.object({
  tickets: z.array(syncTicket),
  devices: z.array(
    z.object({ id: uuid, gate: gateName, direction: deviceDirection, revoked: z.boolean() }),
  ),
  /** Current ticket types (early-entry minutes can change), so devices need not re-enrol. */
  ticket_types: z.array(scannerTicketType).default([]),
  next_cursor: cursor.nullable(),
  has_more: z.boolean(),
  /** Hub time, Unix seconds, so devices can correct their clock. */
  hub_time: unixSeconds,
});

/** `POST /scans`: outbox scans recorded offline. */
export const hubScansRequest = z.object({ scans: z.array(scanRecord).min(1).max(500) });
export const hubScansResponse = z.object({ acknowledged: z.array(uuid), conflicts: z.array(uuid) });

/** `GET /health`. */
export const healthResponse = z.object({
  ok: z.literal(true),
  mode: z.enum(["hub", "server"]),
  last_cloud_sync_at: unixSeconds.nullable(),
});
